    ${groups.map(g =&gt; html`&lt;div&gt;${g.title}${g.panel}&lt;/div&gt;`)}
    &lt;div class="sb-title"&gt;Estimates with 95% CIs&lt;/div&gt;
    ${estimatesPlot}
  &lt;/div&gt;`
}







